import{_ as a,o,c as r,af as t}from"./chunks/framework.zl0XNxp1.js";const p=JSON.parse('{"title":"丽江 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/LiJiang.md","filePath":"2_articles/travel_record/LiJiang.md"}'),c={name:"2_articles/travel_record/LiJiang.md"};function d(i,e,l,n,_,s){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="丽江-2025" tabindex="-1">丽江 - 2025 <a class="header-anchor" href="#丽江-2025" aria-label="Permalink to &quot;丽江 - 2025&quot;">​</a></h1><h2 id="_6月12日-6月13日-☀️" tabindex="-1">6月12日 - 6月13日 ☀️ <a class="header-anchor" href="#_6月12日-6月13日-☀️" aria-label="Permalink to &quot;6月12日 - 6月13日 ☀️&quot;">​</a></h2><blockquote><p>我和黛黛同学本科毕业旅行的第三站！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>云南三部曲之<code>丽江</code>, 但由于丽江的景点实在是相隔太远，而且我俩忘记准备厚点的衣服，索性就只在丽江市区玩一天。</p><h3 id="_6月12日" tabindex="-1">6月12日 <a class="header-anchor" href="#_6月12日" aria-label="Permalink to &quot;6月12日&quot;">​</a></h3><p>从大理坐高铁到丽江后已经晚上八点多，坐丽江高铁站到丽江古城的专运公交到达古城，又打车去民宿，结果酒店名字打错一个字，到了一个不知名的地方.....又重新打车后爬半天楼梯才到民宿，在丽江订的民宿很有本地少数民族风格(红色的那种)，给黛黛吓得不敢睡觉，而且丽江的气候是真的潮湿，被子跟洗了就没晒一样湿，难受的将就了一晚上。</p><h3 id="_6月13日" tabindex="-1">6月13日 <a class="header-anchor" href="#_6月13日" aria-label="Permalink to &quot;6月13日&quot;">​</a></h3><p>一大早起来吃了早饭，我们就去了<code>丽江古城</code>，应该是本地人习惯昼伏夜出，古城都没啥店开门，在里面干逛了好几个小时，打卡了<code>大水车</code>、<code>黑龙潭</code>、<code>四方街</code>......中午在丽江给家里人买了云南特产松露酒、普洱茶和菌汤包，还吃了牦牛肉(确实香但是巨贵)，午饭在本地苍蝇小馆里吃了特色菜，味道确实可以，也很便宜。下午太热我们就去了沃尔玛，给我们搭配了一身<code>行政情侣风</code>的衣服哈哈，又买了零食饮料回到酒店取行李，但买的特产和衣服实在太多，行李箱完全放不下了，就把一些不用的东西送给了民宿老板(老板人非常好也是外地人)，然后打车去丽江火车站，出发前往毕业旅行第四站<code>香格里拉</code>。</p><p><code>最后更新时间：2025-07-23 21:59:15</code></p>',10)])])}const u=a(c,[["render",d]]);export{p as __pageData,u as default};
